      if (strictMode && curIndex >= buffer.byteLength - 1) {
        throw new Error(
          "Couldn't find datas corresponding to the track #" + i + '.'
        );
      }

      track = new MIDIFileTrack(buffer, curIndex, strictMode);
      this.tracks.push(track);

      curIndex += track.getTrackLength() + 8;
