function _getPath(o, pathSegments) {
  if (o == null) {
    return undefined;
  }

  var head = pathSegments[0],
      tail = pathSegments.slice(1);

  if (Array.isArray(o) && !(head in o)) {
    o = o.reduce(function (acc, x) {
      if (!x) {
        return acc;
      }

      var y = x[head];

      if (Array.isArray(y)) {
        acc.push.apply(acc, y);
      } else {
        acc.push(y);
      }

      return acc;
    }, []);
  } else {
    o = o[head];
  }

  if (!tail.length) {
    return o;
  } else {
    return o ? _getPath(o, tail) : undefined;
  }
}

