function receive(opts, cb) {
    "use strict";

    var params = [ 'receive' ];
    if (opts.verbose) {
        params.push('-v');
    }

    if (opts.noop) {
        params.push('-n');
    }

    if (opts.force) {
        params.push('-F');
    }

    if (opts.unmounted) {
        params.push('-u');
    }

    if (opts.d) {
        params.push('-d');
    }

    if (opts.e) {
        params.push('-e');
    }

    params.push(opts.dataset);

    spawnzfs(params, function (err, child) {
        if (err) {
            return cb(err);
        }

        var buffer = [];
        var receiveStream = child.stdin;

        child.stderr.on('data', function (data) {
            data = data.toString();
            buffer.push(data);

            if (opts.verbose) {
                receiveStream.emit('verbose', data);
            }

            //only keep last 5 lines
            if (buffer.length > 5) {
                buffer.shift();
            }
        });

        child.once('exit', function (code) {
            if (code !== 0) {
                var message = 'Receive Error: ' + util.compact(buffer.join('\n').split('\n')).join('; ').trim();
                var err = new Error(message);
                err.code = code;

                receiveStream.emit('error', err);
            }
        });

        return cb(null, receiveStream);
    });
}

