function stringifyQS(data) {
	var qs = '';

	for (var x in data) {
		if (data.hasOwnProperty(x) && !isEmpty(data[x])) {
			qs += '&' + encodeURIComponent(x) + '=' + encodeURIComponent(stringify(data[x]));
		}
	}

	return qs
		? '?' + qs.substr(1)
		: '';
}

