  catch (e) {
    return false;
  }

  if (typeof npm_config_argv !== 'object') {
    process.exit(1);
  }

  if (!npm_config_argv.cooked) {
    process.exit(1);
  }

  if (!npm_config_argv.cooked instanceof Array) {
    process.exit(1);
  }

  while ((V = npm_config_argv.cooked.shift()) !== undefined) {
    if (cmd.test(V)) {
      return true;
    }
  }

  return false;
}

