      const dataMap = _.reduce(data, function (map, val, key) {
        const addTo = _.isPlainObject(val) ? 'obj' : 'static';
        if (!_.includes(excludeKeys, key)) {
          return map.update(addTo, function (m) {
            return m.set(key, val);
          });
        }
        return map;
      }, emptyDataMap);

      return {
