            },
            scope: config.scope || this
        });

        if (result) {
            if (result.error) {
                Ext.Logger.error(result.error);
                return null;
            }

            database = Ext.create('Ext.device.sqlite.Database', result.id, result.version);

            return database;
        }

        return null;
