function pdf( x, mu, sigma ) {
	if ( sigma === 0 ) {
		return x === mu ? Number.POSITIVE_INFINITY : 0;
	}
	var s2 = pow( sigma, 2 ),
		A = 1 / ( sqrt( 2 * s2 * PI ) ),
		B = -1 / ( 2 * s2 );
	return A * exp( B * pow( x - mu, 2 ) );
}

